/**
 * frontend/src/components/CameraRecognition.jsx
 * 🏆 VERSION FUSIONNÉE & OPTIMISÉE (INDUSTRIAL + COMPATIBILITÉ)
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

// CONFIGURATION
const COLORS = {
  primary: '#6366F1',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  surface: '#FFFFFF',
  background: '#F8FAFC',
  text: '#1E293B'
};

const CameraRecognition = ({ addNotification }) => {
  // REFS
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);
  const isProcessingRef = useRef(false);
  const autoModeRef = useRef(true); // Ref pour la boucle logicielle

  // STATES (UI)
  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(true);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [frameCount, setFrameCount] = useState(0);
  const [error, setError] = useState(null);

  // Synchroniser la ref avec l'état pour la boucle de capture
  useEffect(() => {
    autoModeRef.current = autoMode;
  }, [autoMode]);

  /**
   * 🎥 DÉMARRAGE CAMÉRA (Persistant)
   */
  const startCamera = async () => {
    try {
      console.log('🎥 Démarrage caméra...');
      setLoading(true);
      setError(null);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        // On attend que la vidéo soit prête pour lancer la boucle
        videoRef.current.onloadedmetadata = () => {
          setCameraActive(true);
          setLoading(false);
          startCaptureLoop();
        };
      }
    } catch (err) {
      console.error('❌ Erreur caméra:', err);
      setError("Impossible d'accéder à la caméra");
      setLoading(false);
    }
  };

  /**
   * 🛑 ARRÊT CAMÉRA
   */
  const stopCamera = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    if (videoRef.current) videoRef.current.srcObject = null;
    setCameraActive(false);
    setAutoMode(false);
  }, []);

  /**
   * 🔄 BOUCLE DE CAPTURE (Optimisée)
   */
  const startCaptureLoop = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    const capture = async () => {
      // 1. Verrous de sécurité
      if (!autoModeRef.current || !videoRef.current || isProcessingRef.current) {
        timeoutRef.current = setTimeout(capture, 500);
        return;
      }

      // 2. Capture de l'image (Méthode de ton ancien code qui marchait)
      try {
        const video = videoRef.current;
        if (video.readyState < 2) throw new Error("Video not ready");

        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth || 1280;
        canvas.height = video.videoHeight || 720;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0);

        // On utilise la qualité 0.92 comme dans ton manuel
        const imageBase64 = canvas.toDataURL('image/jpeg', 0.92);

        isProcessingRef.current = true;
        setFrameCount(prev => prev + 1);

        // 3. Appel API
        const response = await attendanceAPI.recognize(imageBase64);
        const data = response?.data;

        if (data && data.success && data.student) {
          handleSuccess(data, imageBase64);
          // Pause de 3 secondes comme dans ton ancien code
          isProcessingRef.current = false;
          timeoutRef.current = setTimeout(capture, 3000); 
        } else {
          isProcessingRef.current = false;
          timeoutRef.current = setTimeout(capture, 1000); // Réessayer dans 1s
        }

      } catch (err) {
        console.warn("⚠️ Loop error:", err.message);
        isProcessingRef.current = false;
        timeoutRef.current = setTimeout(capture, 2000);
      }
    };

    capture();
  };

  const handleSuccess = (data, image) => {
    setResult({
      success: true,
      name: data.student,
      email: data.email || 'N/A',
      confidence: (data.confidence * 100).toFixed(1),
      attendanceId: data.attendance_id,
      timestamp: new Date().toLocaleTimeString(),
      image: image // On stocke l'image de la capture
    });

    if (addNotification) {
      addNotification(`✅ ${data.student} enregistré !`, 'success');
    }
  };

  // Cleanup au démontage
  useEffect(() => { return () => stopCamera(); }, [stopCamera]);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>👤 Système de Présence IA</h2>

        {/* VIDEO FIX: Toujours dans le DOM */}
        <div style={styles.videoWrapper}>
          <video
            ref={videoRef}
            autoPlay
            muted
            playsInline
            style={{ ...styles.video, display: cameraActive ? 'block' : 'none' }}
          />
          {!cameraActive && (
            <div style={styles.placeholder}>
              <p>Caméra Inactive</p>
            </div>
          )}
          {autoMode && cameraActive && <div style={styles.scanLine} />}
        </div>

        <div style={styles.controls}>
          {!cameraActive ? (
            <button onClick={startCamera} style={styles.btnStart}>▶️ Activer Caméra</button>
          ) : (
            <>
              <button 
                onClick={() => setAutoMode(!autoMode)} 
                style={{ ...styles.btn, background: autoMode ? COLORS.warning : COLORS.primary }}
              >
                {autoMode ? '⏸️ Pause Auto' : '🔄 Relancer Auto'}
              </button>
              <button onClick={stopCamera} style={styles.btnStop}>🛑 Éteindre</button>
            </>
          )}
        </div>

        {result && (
          <div style={{ ...styles.resultBox, borderLeftColor: result.success ? COLORS.success : COLORS.danger }}>
            <div style={styles.resultHeader}>
              <img src={result.image} alt="capture" style={styles.thumb} />
              <div>
                <h3 style={{ margin: 0, color: COLORS.success }}>{result.name}</h3>
                <p style={{ margin: 0, fontSize: '0.8rem', color: '#666' }}>Détecté à {result.timestamp}</p>
              </div>
            </div>
            <div style={styles.resultGrid}>
              <span>🎯 Confiance: <b>{result.confidence}%</b></span>
              <span>🆔 ID: <b>{result.attendanceId}</b></span>
              <span style={{ gridColumn: '1 / -1' }}>📧 {result.email}</span>
            </div>
          </div>
        )}

        <div style={styles.footer}>
          <span>Frames: <b>{frameCount}</b></span>
          <span>Status: <b>{autoMode ? 'Scanning' : 'Standby'}</b></span>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: { padding: '20px', backgroundColor: COLORS.background, minHeight: '100vh', display: 'flex', justifyContent: 'center' },
  card: { width: '100%', maxWidth: '600px', backgroundColor: COLORS.surface, borderRadius: '20px', padding: '25px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' },
  title: { textAlign: 'center', marginBottom: '20px', color: COLORS.text },
  videoWrapper: { position: 'relative', width: '100%', borderRadius: '15px', overflow: 'hidden', backgroundColor: '#000', aspectRatio: '16/9' },
  video: { width: '100%', height: '100%', objectFit: 'cover' },
  placeholder: { height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff' },
  scanLine: { position: 'absolute', top: 0, left: 0, width: '100%', height: '2px', background: COLORS.primary, boxShadow: `0 0 15px ${COLORS.primary}`, animation: 'scan 2s linear infinite' },
  controls: { display: 'flex', gap: '10px', marginTop: '20px' },
  btn: { flex: 1, padding: '12px', border: 'none', borderRadius: '10px', color: '#fff', fontWeight: 'bold', cursor: 'pointer' },
  btnStart: { width: '100%', padding: '15px', backgroundColor: COLORS.success, color: '#fff', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' },
  btnStop: { padding: '12px', backgroundColor: 'transparent', border: `1px solid ${COLORS.danger}`, color: COLORS.danger, borderRadius: '10px', cursor: 'pointer' },
  resultBox: { marginTop: '20px', padding: '15px', backgroundColor: '#F0FDF4', borderRadius: '12px', borderLeft: '5px solid' },
